import{_ as i,W as l,s as o,u as r,ah as d,I as p,w as e,Z as t,A as n}from"./chunks/framework.Dx7wo2et.js";import"./chunks/theme.CjgFg8Ql.js";const L=JSON.parse('{"title":"将安装了 CentOS/RHEL 6/7 的机器转变成路由器 | LCTT x X-CMD","titleTemplate":false,"description":"将安装了 CentOS/RHEL 6/7 的机器转变成路由器 | LCTT (201712) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"将安装了 CentOS/RHEL 6/7 的机器转变成路由器 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"将安装了 CentOS/RHEL 6/7 的机器转变成路由器 | LCTT (201712) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201712/20171213 Turning a CentOS-RHEL 6 or 7 machine into a router","title":"将安装了 CentOS/RHEL 6/7 的机器转变成路由器","tag":"201712"},"relativePath":"201712/20171213 Turning a CentOS-RHEL 6 or 7 machine into a router.md","filePath":"[post].md"}'),h={name:"201712/20171213 Turning a CentOS-RHEL 6 or 7 machine into a router.md"};function c(u,a,g,b,m,C){const s=l("Link");return r(),o("div",null,[a[13]||(a[13]=d(`<h1 id="将安装了-centos-rhel-6-7-的机器转变成路由器" tabindex="-1">将安装了 CentOS/RHEL 6/7 的机器转变成路由器 <a class="header-anchor" href="#将安装了-centos-rhel-6-7-的机器转变成路由器" aria-label="Permalink to 将安装了 CentOS/RHEL 6/7 的机器转变成路由器">​</a></h1><p>在本文中，我们将学习通过使用 NAT 技术将安装有 RHEL/CentOS 6 &amp; 7 的机器转变成路由器来用。 我们都知道，路由器是一个工作在第三层的网络设备，用于将两个或多个网络连接在一起，即，将局域网连接上广域网上或者局域网直接互联。 路由器非常昂贵，尤其对于小型组织来说更是如此，这可能是我们关注路由器的一个原因。 与其使用专用硬件，不如让我们用 Linux 机器转换成路由器来用。</p><p>RHEL/CentOS 6 和 7 上的操作过程我们都会讲。但在开始之前， 让我们先看看需要准备那些东西。</p><h3 id="前期条件" tabindex="-1">前期条件 <a class="header-anchor" href="#前期条件" aria-label="Permalink to 前期条件">​</a></h3><p>1、 一台装有 RHEL/CentOS 6 或 7 的机器</p><p>2、两块分别配有本地 IP 和外网 IP 的网卡</p><p>我们需要为两个网卡都分配 IP 地址，一个本地网络的 IP（由我们的网络管理员提供），另一个是互联网 IP（由 ISP 提供）。 像这样：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Ifcfg-en0s3 192.168.1.1 (LAN IP address)</span></span>
<span class="line"><span>Ifcfg-en0s5 10.1.1.1  (WAN IP address)</span></span></code></pre></div><p><strong>注意</strong> 不同 Linux 发行版的网卡名是不一样的。</p><p>现在准备工作完成了，可以进行配置了。</p><h3 id="步骤-1-启用-ip-转发" tabindex="-1">步骤 1 启用 IP 转发 <a class="header-anchor" href="#步骤-1-启用-ip-转发" aria-label="Permalink to 步骤 1 启用 IP 转发">​</a></h3><p>第一步，我们启用 IP 转发。 这一步在 RHEL/CentOS 6 和 7 上是相同的。 运行</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ sysctl -w net.ipv4.ip_forward=1</span></span></code></pre></div><p>但是这样会在系统重启后恢复。要让重启后依然生效需要打开</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ vi /etc/sysctl.conf</span></span></code></pre></div><p>然后输入下面内容，</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>net.ipv4.ip_forward = 1</span></span></code></pre></div><p>保存并退出。现在系统就启用 IP 转发了。</p><h3 id="步骤-2-配置-iptables-firewalld-的规则" tabindex="-1">步骤 2 配置 IPtables/Firewalld 的规则 <a class="header-anchor" href="#步骤-2-配置-iptables-firewalld-的规则" aria-label="Permalink to 步骤 2 配置 IPtables/Firewalld 的规则">​</a></h3><p>下一步我们需要启动 IPtables/firewalld 服务并配置 NAT 规则，</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ systemctl start firewalld (For Centos/RHEL 7)</span></span>
<span class="line"><span>$ service iptables start  (For Centos/RHEL 6)</span></span></code></pre></div><p>然后运行下面命令来配置防火墙的 NAT 规则：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>CentOS/RHEL 6</span></span>
<span class="line"><span>$ iptables -t nat -A POSTROUTING -o XXXX -j MASQUERADE</span></span>
<span class="line"><span>$ service iptables restart </span></span>
<span class="line"><span>CentOS/RHEL 7</span></span>
<span class="line"><span>$ firewall-cmd  -permanent -direct -passthrough ipv4 -t nat -I POSTROUTING -o XXXX -j MASQUERADE -s 192.168.1.0/24</span></span>
<span class="line"><span>$ systemctl restart firewalld</span></span></code></pre></div><p>这里，<code>XXXX</code> 是配置有外网 IP 的那个网卡名称。 这就将 Linux 机器配置成了路由器了， 下面我们就可以配置客户端然后测试路由器了。</p><h3 id="步骤-3-配置客户端" tabindex="-1">步骤 3 配置客户端 <a class="header-anchor" href="#步骤-3-配置客户端" aria-label="Permalink to 步骤 3 配置客户端">​</a></h3><p>要测试路由器，我们需要在客户端的网关设置成内网 IP， 本例中就是 192.168.1.1。 因此不管客户机是 Windows 还是 Linux， 请先确保网关是 192.168.1.1。 完成后， 打开终端或命令行并 <code>ping</code> 一个网站来测试客户端是否能访问互联网了：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ ping google.com</span></span></code></pre></div><p>我们也可以通过网络浏览器访问网站的方式来检查。</p><hr>`,29)),p("p",null,[a[1]||(a[1]=e("via: ")),t(s,{href:"http://linuxtechlab.com/turning-centosrhel-6-7-machine-router/"},{default:n(()=>a[0]||(a[0]=[e("http://linuxtechlab.com/turning-centosrhel-6-7-machine-router/")])),_:1})]),p("p",null,[a[5]||(a[5]=e("作者：")),t(s,{href:"http://linuxtechlab.com/author/shsuain/"},{default:n(()=>a[2]||(a[2]=[e("Shusain")])),_:1}),a[6]||(a[6]=e(" 译者：")),t(s,{href:"https://github.com/lujun9972"},{default:n(()=>a[3]||(a[3]=[e("lujun9972")])),_:1}),a[7]||(a[7]=e(" 校对：")),t(s,{href:"https://github.com/wxy"},{default:n(()=>a[4]||(a[4]=[e("wxy")])),_:1})]),p("p",null,[a[10]||(a[10]=e("本文由 ")),t(s,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>a[8]||(a[8]=[e("LCTT")])),_:1}),a[11]||(a[11]=e(" 原创编译，")),t(s,{href:"https://linux.cn/"},{default:n(()=>a[9]||(a[9]=[e("Linux中国")])),_:1}),a[12]||(a[12]=e(" 荣誉推出"))])])}const T=i(h,[["render",c]]);export{L as __pageData,T as default};
